  const headerTemplate = (() => { const lines = (skeleton || '').replace(/\r\n/g, '\n').split('\n'); const si = lines.findIndex(l => l.trim() === '%%% HEADER_START'); if (si === -1) return ''; const ei = lines.findIndex((l, i) => i > si && l.trim() === '%%% HEADER_END'); if (ei === -1) return ''; return lines.slice(si + 1, ei).join('\n').trim(); })();
  const headerLatex = headerTemplate.replace('{{NAME}}', escapeLatexText(personal.name || '')).replace('{{PHONE}}', escapeLatexText(personal.phone_display || personal.phone_primary || '')).replace('{{EMAIL}}', personal.email || '').replace('{{LINKEDIN}}', personal.linkedin || '').replace('{{PORTFOLIO_LINE}}', '').replace('{{GITHUB_LINE}}', '').replace('{{LOCATION_LINE}}', '');
  const sections = revisedJson.sections || [];
  const contentParts = [];
  for (const section of sections) {
    const heading = section.heading || '';
    const items = section.items || [];
    if (heading === 'Skills' || heading === 'Technical Skills') {
      contentParts.push('\\section{Technical Skills}\n\\resumeSubHeadingListStart');
      for (const item of items) { if (item.type === 'skill_line') contentParts.push('  \\resumeSkillLine{' + escapeLatexText(item.category || '') + '}{' + escapeLatexText(item.skills || '') + '}'); }
      contentParts.push('\\resumeSubHeadingListEnd');
    } else if (heading === 'Education') {
      contentParts.push('\\section{Education}\n\\resumeSubHeadingListStart');
      for (const item of items) { if (item.type === 'education') { const degree = [item.degree, item.major].filter(Boolean).join(' in '); contentParts.push('  \\resumeSubheading{' + escapeLatexText(item.institution || '') + '}{' + escapeLatexText(item.location || '') + '}{' + escapeLatexText(degree) + '}{' + escapeLatexText(item.dates || '') + '}'); } }
      contentParts.push('\\resumeSubHeadingListEnd');
    } else if (heading === 'Experience') {
      contentParts.push('\\section{Experience}\n\\resumeSubHeadingListStart');
      for (const item of items) {
        if (item.type === 'role') {
          contentParts.push('  \\resumeSubheading{' + escapeLatexText(item.role || '') + '}{' + escapeLatexText(item.dates || '') + '}{' + escapeLatexText(item.company || '') + '}{' + escapeLatexText(item.location || '') + '}');
          if (item.bullets && item.bullets.length > 0) { contentParts.push('  \\resumeItemListStart'); for (const b of item.bullets) { const kw = b.keyword ? '\\textbf{' + escapeLatexText(cleanText(b.keyword)) + ':} ' : ''; contentParts.push('    \\resumeItem{' + kw + escapeLatexText(cleanText(b.text || '')) + '}'); } contentParts.push('  \\resumeItemListEnd'); }
        }
      }
      contentParts.push('\\resumeSubHeadingListEnd');
    } else if (heading === 'Projects') {
      contentParts.push('\\section{Projects}\n\\resumeSubHeadingListStart');
      for (const item of items) {
        if (item.type === 'project') {
          contentParts.push('  \\resumeProjectHeading{\\textbf{' + escapeLatexText(item.name || '') + '}' + (item.tech ? ' $|$ ' + escapeLatexText(item.tech) : '') + '}{' + (item.url ? escapeLatexText(item.url) : '') + '}');
          if (item.bullets && item.bullets.length > 0) { contentParts.push('  \\resumeItemListStart'); for (const b of item.bullets) { const kw = b.keyword ? '\\textbf{' + escapeLatexText(cleanText(b.keyword)) + ':} ' : ''; contentParts.push('    \\resumeItem{' + kw + escapeLatexText(cleanText(b.text || '')) + '}'); } contentParts.push('  \\resumeItemListEnd'); }
        }
      }
      contentParts.push('\\resumeSubHeadingListEnd');
    }
  }
  const fullLatex = wrapResumeWithSkeleton({ skeleton, headerLatex, contentLatex: contentParts.join('\n') });
  return [{ json: { latex: normalizeLatexForPdflatex(fullLatex), chat_id: ctx.chat_id, job_title: ctx.last_apply.job_title, company: ctx.last_apply.company, revise_type: 'resume', changes_summary: revisedJson.changes_summary || '' } }];
}

const staticData = $getWorkflowStaticData('global');
const ctx = $('Load Revise Context').first().json;
const revised = $('ReviseForge').first().json.output || {};
const type = ctx.last_apply.revise_type;
if (type === 'cover') { staticData.last_apply.cover_json = revised; } else { staticData.last_apply.resume_json = revised; }
staticData.last_apply.timestamp = new Date().toISOString();
const summary = revised.changes_summary || 'Updated.';
return [{ json: { chat_id: ctx.chat_id, message: "\u270F\uFE0F *Updated!* " + summary + "\n\nMore tweaks? Just describe what you want changed." } }];

const chatId = $('Extract Input').first().json.chat_id;
const routerOutput = $('Route Intent').first().json.output || {};
const entities = routerOutput.entities || {};
const intent = routerOutput.intent || 'outreach';
const msgText = $('Extract Input').first().json.message_text || '';
const draftMatch = msgText.match(/draft\s*(\d+)/i);
if (draftMatch && intent === 'outreach') return [{ json: { chat_id: chatId, research_type: 'draft', draft_number: parseInt(draftMatch[1]), company: entities.company || null, role: entities.role || null, queries: [] } }];
const company = entities.company || 'Unknown';
const role = entities.role || 'Software Engineer';
const location = entities.location || '';
const year = new Date().getFullYear();
let queries = [];
if (intent === 'intel') {
  queries = ['site:layoffs.fyi ' + company + ' OR ' + company + ' layoffs ' + (year - 1) + ' ' + year, company + ' employee reviews glassdoor OR site:teamblind.com ' + company + ' culture', 'site:levels.fyi ' + company + ' salary compensation', company + ' H1B sponsorship visa ' + (year - 1) + ' OR site:h1bdata.info ' + company, company + ' funding round valuation ' + year + ' techcrunch', company + ' leadership principles core values careers'];
} else {
  const loc = location ? ' ' + location : '';
  queries = [
    company + ' ' + role + ' hiring manager site:linkedin.com/in' + loc,
    company + ' director engineering ' + role + ' site:linkedin.com/in' + loc,
    company + ' senior manager ' + role + ' site:linkedin.com/in' + loc,
    company + ' ' + role + ' team lead site:linkedin.com/in' + loc,
    company + ' technical recruiter ' + role + loc + ' LinkedIn',
  ];
}
return [{ json: { chat_id: chatId, research_type: intent, company, role, location, queries, draft_number: null } }];

const r = $input.first().json.output || {};
const ctx = $('Normalize Research Results').first().json;
const recIcon = r.recommendation === 'Apply' ? '\u2705' : r.recommendation === 'Caution' ? '\u26A0\uFE0F' : '\u{1F6D1}';
const sections = [
  recIcon + ' *' + (r.company || ctx.company) + ' \u2014 Health Score: ' + (r.health_score || '?') + '/100*',
  '_' + (r.summary || 'No summary available.') + '_', '',
  '\u{1F4CA} *Sentiment:* ' + (r.sentiment && r.sentiment.overall_mood || 'Unknown') + (r.sentiment && r.sentiment.glassdoor_rating ? ' (Glassdoor: ' + r.sentiment.glassdoor_rating + ')' : ''),
];
if (r.sentiment && r.sentiment.positives && r.sentiment.positives.length) sections.push(r.sentiment.positives.map(p => '  \u2705 ' + p).join('\n'));
if (r.sentiment && r.sentiment.negatives && r.sentiment.negatives.length) sections.push(r.sentiment.negatives.map(p => '  \u274C ' + p).join('\n'));
sections.push('');
sections.push('\u{1F534} *Layoffs:* ' + (r.layoffs && r.layoffs.has_recent_layoffs ? 'Yes \u2014 ' + r.layoffs.details : 'None recent'));
sections.push('\u{1F4B0} *Funding:* ' + (r.funding && r.funding.stage || 'Unknown') + (r.funding && r.funding.last_round ? ' (' + r.funding.last_round + ')' : ''));
sections.push('\u{1F6C2} *H1B:* ' + (r.h1b && r.h1b.sponsors ? 'Yes' : 'Unknown'));
sections.push('');
if (r.green_flags && r.green_flags.length) sections.push('\u{1F7E2} *Green Flags:*\n' + r.green_flags.map(f => '\u2022 ' + f).join('\n'));
if (r.red_flags && r.red_flags.length) sections.push('\u{1F534} *Red Flags:*\n' + r.red_flags.map(f => '\u2022 ' + f).join('\n'));
return [{ json: { chat_id: ctx.chat_id, message: sections.filter(Boolean).join('\n') } }];

const result = $input.first().json.output || {};
const ctx = $('Normalize Research Results').first().json;
const staticData = $getWorkflowStaticData('global');
const contacts = result.contacts || [];
staticData.last_contacts = { contacts, company: ctx.company, role: ctx.role, timestamp: new Date().toISOString() };
if (contacts.length === 0) { const tips = (result.search_tips || []).map(t => '• ' + t).join('
'); return [{ json: { chat_id: ctx.chat_id, message: '\u{1F4E7} *No contacts found for ' + ctx.company + '.*

' + (tips ? '*Search Tips:*
' + tips : 'Try a more specific role.') } }]; }
const lines = contacts.map((c, i) => { const priIcon = c.priority === 'High' ? '\u{1F525}' : c.priority === 'Medium' ? '⭐' : '\u{1F4CC}'; const linkedIn = c.linkedin_url ? ' [LinkedIn](' + c.linkedin_url + ')' : ''; return (i + 1) + '. ' + priIcon + ' *' + c.name + '* — ' + c.role + '
   ' + c.type + ' | ' + (c.location || '?') + ' | Confidence: ' + c.confidence + linkedIn + '
   _' + c.reason + '_'; });
return [{ json: { chat_id: ctx.chat_id, message: '\u{1F4E7} *Contacts at ' + ctx.company + ':*

' + lines.join('

') + '

\u{1F4A1} Reply "draft 1" to generate outreach for contact #1.' } }];

const staticData = $getWorkflowStaticData('global');
const chatId = $('Extract Input').first().json.chat_id;
const ctx = $('Prepare Research').first().json;
const draftNum = ctx.draft_number;
const lastContacts = staticData.last_contacts;
if (!lastContacts || !lastContacts.contacts || lastContacts.contacts.length === 0) return [{ json: { chat_id: chatId, error: 'No contacts to draft for. Run /outreach first.' } }];
const idx = draftNum - 1;
if (idx < 0 || idx >= lastContacts.contacts.length) return [{ json: { chat_id: chatId, error: 'Contact #' + draftNum + ' not found. You have ' + lastContacts.contacts.length + ' contacts.' } }];
const contact = lastContacts.contacts[idx];
const resumeData = staticData.last_apply || {};
return [{ json: { chat_id: chatId, contact, company: lastContacts.company, role: lastContacts.role, candidate_name: (resumeData.personal && resumeData.personal.name) || 'Candidate', candidate_location: (resumeData.personal && resumeData.personal.location) || '', relevant_achievement: resumeData.resume_text ? resumeData.resume_text.substring(0, 500) : '', error: '' } }];

// Parse Scorer Output (repurposed, S13) — turns the matcher service response into
// the `scored` array the rest of the find pipeline expects. Keeps job_id + score100
// so Record Matches (Postgres insert) and Build Telegraph Body keep working, and
// adds the match%/skill fields for the JobRight display. Dead jobs (matcher dropped)
// are already absent. Degrades to empty scored on a matcher failure (never throws).
const m = $input.first().json || {};
const results = Array.isArray(m.results) ? m.results : [];
const dropped = Array.isArray(m.dropped) ? m.dropped : [];

const scored = results.map((r) => {
  const sk = r.skill_match || {};
  const matched = sk.matched || [];
  const missing = sk.missing || [];
  const adjacent = (sk.adjacent || []).map((a) => (a && a.skill ? a.skill : a)).filter(Boolean);
  const mp = Math.max(0, Math.min(100, Math.round(r.match_pct || 0)));
  let one = '';
  if (matched.length) one = 'Matches ' + matched.slice(0, 4).join(', ') + (missing.length ? ' -- gaps: ' + missing.slice(0, 2).join(', ') : '');
  else if (adjacent.length) one = 'Transferable: ' + adjacent.slice(0, 3).join(', ');
  else if (missing.length) one = 'Missing ' + missing.slice(0, 3).join(', ');
  return {
    job_id: r.id,
    match_pct: mp,
    score100: mp,                       // Record Matches reads score100
    fit_score: Math.round(mp / 10),
    rerank: r.rerank_score != null ? r.rerank_score : null,
    skill_coverage: sk.coverage != null ? sk.coverage : 0,
    matched_skills: matched,
    missing_skills: missing,
    adjacent_skills: adjacent,
    validated: r.validated || 'not_checked',
    one_liner: one,
    bin: mp >= 70 ? 'Strong' : mp >= 55 ? 'Good' : mp >= 40 ? 'Mixed' : 'Poor',
  };
});

return [{ json: { scored, total: scored.length, strategy: 'matcher', dropped } }];

// Parse Expand Query v2 — unified intent schema
// Parses LLM output, merges user_prefs, fails loudly on bad output.

const sd = $getWorkflowStaticData('global');
const userPrefs = sd.user_prefs || {};

let llmOutput = '';
try {
  const raw = $input.first().json;
  llmOutput = raw.text || raw.output || raw.response || raw.content || JSON.stringify(raw);
} catch(e) { llmOutput = ''; }

llmOutput = llmOutput.replace(/^```json\s*/i,'').replace(/^```\s*/i,'').replace(/```\s*$/i,'').trim();

let parsed = null;
try { parsed = JSON.parse(llmOutput); } catch(e) {
  const m = llmOutput.match(/\{[\s\S]*\}/);
  if (m) { try { parsed = JSON.parse(m[0]); } catch(e2) {} }
}

if (!parsed) {
  return [{ json: {
    _parse_error: true,
    error_message: "⚠️ I couldn't understand that query. Try something like:\n\n• \"find me AI Engineer jobs in NYC\"\n• \"show remote ML roles, $150k+\"\n• \"search for backend jobs in San Francisco\"",
    raw_output: llmOutput.substring(0, 200)
  }}];
}

if (!parsed.role_families || !Array.isArray(parsed.role_families) || !parsed.role_families.length) {
  return [{ json: {
    _parse_error: true,
    error_message: "⚠️ Couldn't figure out what role you're looking for. Could you be more specific?\n\n• \"find me Data Engineer jobs\"\n• \"show ML Engineer openings, remote\""
  }}];
}

const result = {
  role_families:      parsed.role_families,
  excluded_roles:     parsed.excluded_roles     || userPrefs.excluded_roles     || ["Technical Support","Customer Success","QA Engineer"],
  firecrawl_queries:  parsed.firecrawl_queries   || [],
  youcom_queries:     parsed.youcom_queries       || [],
  serper_queries:     parsed.serper_queries       || [],
  location_canonical: parsed.location_canonical   || userPrefs.location_canonical || null,
  country:            parsed.country              || userPrefs.country             || null,
  remote_preference:  parsed.remote_preference    || userPrefs.remote_preference   || 'open',
  freshness:          parsed.freshness            || userPrefs.freshness           || 'qdr:w',
  seniority:          parsed.seniority            || userPrefs.seniority           || 'any',
  max_yoe:            parsed.max_yoe !== undefined ? parsed.max_yoe : (userPrefs.max_yoe || null),
  industry_signals:   parsed.industry_signals     || [],
  visa_signals:       parsed.visa_signals         || [],
  salary_signals:     parsed.salary_signals       || [],
  scoring_priorities: parsed.scoring_priorities   || [],
  verbose:            parsed.verbose              || userPrefs.verbose             || false,
  _schema_version:    2,
  _parsed_at:         new Date().toISOString()
};

// Save for apply flow
// S4: rich structured filters + F-1 OPT ambiguity flag
result.salary_min = (typeof parsed.salary_min === 'number' ? parsed.salary_min : (userPrefs.salary_min || null));
result.equity = !!parsed.equity;
result.sponsorship_required = !!(parsed.sponsorship_required || userPrefs.sponsorship_required);
result.f1_opt_constraint = parsed.f1_opt_constraint || 'none';
result.exclude_recent_layoffs = !!parsed.exclude_recent_layoffs;
result.min_funding_stage = parsed.min_funding_stage || null;
result.culture_constraints = Array.isArray(parsed.culture_constraints) ? parsed.culture_constraints : [];
result.ambiguity_flags = [];
if (result.f1_opt_constraint === 'remote_from_outside_us') {
  result.ambiguity_flags.push('F1_OPT_REMOTE_LOCATION');
  result._f1_note = '🛂 Heads-up: on F-1 OPT, remote work must be performed while physically in the US. I searched anyway, but a US-based role worked from outside the US generally is NOT OPT-eligible — confirm you will be in the US.';
}
// S1: intern/level intent + non-blocking intern clarifier
result.level_intent = parsed.level_intent || 'any';
result.include_interns = !!(parsed.include_interns || parsed.level_intent === 'internship' || userPrefs.include_interns);
result.ambiguity_flags = result.ambiguity_flags || [];
if (!result.include_interns && result.level_intent === 'any') {
  result.ambiguity_flags.push('INTERN_CLARIFY');
  result._intern_note = "\uD83C\uDF93 _Hiding intern/trainee roles -- add 'intern' to your search to include them._";
}
// C1: GENERIC company targeting -- NO hardcoded alias table. The LLM is the
// extractor (and may itself list alternate brand names / subsidiaries it knows);
// we just turn each name it returns into a normalized token regex. Multi-word
// names match flexibly ("Goldman Sachs" -> "goldman.*sachs"). \y/\b-bounded at use.
result.companies = Array.isArray(parsed.companies) ? parsed.companies.filter(Boolean) : [];
{
  const parts = result.companies
    .map(c => String(c).toLowerCase().replace(/[^a-z0-9 ]+/g,' ').trim().split(/\s+/).filter(Boolean).join('.*'))
    .filter(Boolean);
  result.company_rx = parts.length ? Array.from(new Set(parts)).join('|') : null;
}
// P0(D): non-blocking ambiguous-location note (bare 2-letter token country-vs-US-state).
result.location_ambiguous = !!parsed.location_ambiguous;
result.location_note = (typeof parsed.location_note === 'string') ? parsed.location_note : '';
result.ambiguity_flags = result.ambiguity_flags || [];
if (result.location_ambiguous && result.location_note) {
  result.ambiguity_flags.push('LOCATION_CLARIFY');
  result._location_note = '\uD83D\uDCCD ' + result.location_note;
}
sd.last_search_intent = result;

// Build verbose preview message
const filters = [];
if (result.location_canonical) filters.push('📍 ' + result.location_canonical.split(',')[0]);
if (result.salary_signals.length) filters.push('💰 ' + result.salary_signals[0]);
if (result.visa_signals.length) filters.push('🛂 ' + result.visa_signals[0]);
if (result.industry_signals.length) filters.push('🏭 ' + result.industry_signals[0]);
if (result.seniority !== 'any') filters.push('📊 ' + result.seniority);
const remoteIcon = result.remote_preference === 'remote_only' ? ' 🌍 Remote' : '';
result._verbose_message = '🎯 *Searching for:* ' + result.role_families.slice(0,3).join(', ')
  + (result.role_families.length > 3 ? '…' : '') + remoteIcon
  + (filters.length ? '\n' + filters.join(' · ') : '')
  + '\n\n_Reply "edit" to refine, anything else continues._';

return [{ json: result }];

// Build research query. HTTP calls are handled by HTTP Request nodes downstream.
const ctx = $input.first().json;
const company = ctx.company || '';
const researchType = ctx.research_type || 'intel';
const role = ctx.role || 'Software Engineer';
const year = new Date().getFullYear();
const researchQuery = researchType === 'intel'
  ? `Company health analysis for ${company} ${year}: latest news, layoffs, funding rounds, Glassdoor rating, H1B sponsorship, engineering culture, red flags`
  : `Recruiters and hiring managers at ${company} for ${role} positions: LinkedIn profiles, names, titles, contact information`;
return [{ json: { ...ctx, research_query: researchQuery } }];

const jobs = $('Aggregate Jobs').first().json.jobs || [];
const expandCtx = $('Parse Expand Query').first().json;
const maxYoe = expandCtx.max_yoe || null;
const seniorityPref = expandCtx.seniority_pref || 'any';

const seniorityYoe = {
  junior: { min: 0, max: 2 }, 'entry-level': { min: 0, max: 1 }, associate: { min: 0, max: 2 },
  'mid-level': { min: 3, max: 6 }, intermediate: { min: 2, max: 5 },
  senior: { min: 5, max: 99 }, staff: { min: 7, max: 99 },
  principal: { min: 8, max: 99 }, lead: { min: 5, max: 99 },
};

function extractYoe(text) {
  if (!text) return { min: null, max: null };
  const t = text.toLowerCase();
  let m;
  if ((m = t.match(/(\d+)\s*[-–to]+\s*(\d+)\s*(?:years?|yrs?)/i)))
    return { min: parseInt(m[1]), max: parseInt(m[2]) };
  if ((m = t.match(/(\d+)\+\s*(?:years?|yrs?)\s*(?:of\s*)?(?:experience|exp)/i)))
    return { min: parseInt(m[1]), max: 99 };
  if ((m = t.match(/(?:minimum|min\.?|at least)\s*(\d+)\s*(?:years?|yrs?)/i)))
    return { min: parseInt(m[1]), max: 99 };
  if ((m = t.match(/(\d+)\s*(?:years?|yrs?)\s*(?:of\s*)?(?:experience|exp)/i))) {
    const n = parseInt(m[1]);
    return { min: Math.max(0, n - 1), max: n + 2 };
  }
  for (const [label, range] of Object.entries(seniorityYoe)) {
    if (t.includes(label)) return { min: range.min, max: range.max };
  }
  return { min: null, max: null };
}

function calcCompatScore(jobMin, jobMax, userMaxYoe, seniorityPref) {
  if (jobMin === null && jobMax === null) return 1.0;
  if (!userMaxYoe && seniorityPref === 'any') return 1.0;
  let userMin = 0, userMax = userMaxYoe || 99;
  if (seniorityPref === 'junior') { userMin = 0; userMax = Math.min(userMax, 2); }
  else if (seniorityPref === 'mid') { userMin = 2; userMax = Math.min(userMax || 7, 7); }
  else if (seniorityPref === 'senior') { userMin = 5; userMax = 99; }
  const jMin = jobMin ?? 0, jMax = jobMax ?? 99;
  if (userMax >= jMin && userMin <= jMax) return 1.0;
  if (userMin > jMax) return Math.max(0.2, 1.0 - (userMin - jMax) * 0.15);
  if (userMax < jMin) return Math.max(0.1, 1.0 - (jMin - userMax) * 0.2);
  return 1.0;
}

const enrichedJobs = jobs.map(job => {
  const { min, max } = extractYoe(job.description_snippet || job.title || '');
  const compatScore = calcCompatScore(min, max, maxYoe, seniorityPref);
  return { ...job, required_yoe_min: min, required_yoe_max: max, yoe_compat_score: compatScore };
});

const filtered = (maxYoe || seniorityPref !== 'any')
  ? enrichedJobs.filter(j => j.yoe_compat_score >= 0.15)
  : enrichedJobs;

return [{ json: { jobs: filtered, count: filtered.length, filtered_out: enrichedJobs.length - filtered.length } }];

