  const m = pass2 && pass2.bullets && id != null ? pass2.bullets[id] : null;
  if (nonEmptyArr(m)) return m;
  return Array.isArray(fallbackArr) ? fallbackArr : [];
}

function bulletList(items, cap) {
  return (items || [])
    .filter((x) => String(x == null ? '' : x).trim().length)
