// Build Hook Query — S7 (S8: reads the enriched contact when present). Compact,
// ToS-safe outreach-hook search query for the selected contact. PUBLIC sources only
// — GitHub, conference talks, engineering blogs, papers, podcasts. NO LinkedIn
// login-scraping, no bulk social targeting.
function draftCtx() {
  try { const f = $('Finalize Enriched Contact').first().json; if (f && f.contact) return f; } catch (e) {}
  return $('Load Draft Contact').first().json || {};
}
const ctx = draftCtx();
const c = ctx.contact || {};
const name = (c.name || '').trim();
const company = ctx.company || '';
const hook_query = name
  ? '"' + name + '" ' + company + ' (site:github.com OR "conference talk" OR "engineering blog" OR site:arxiv.org OR podcast OR keynote)'
  : company + ' engineering blog OR github OR conference talk';
return [{ json: Object.assign({}, ctx, { hook_query }) }];

// Normalize Hooks — S7. Flatten the Serper hook search into hook_sources and merge
// with the draft context so OutreachWriter gets {contact, candidate_*, company,
// relevant_achievement, candidate_role, contact_location, hook_sources}. Graceful
// on empty/failed search (hook_sources: []).
function draftCtx() {
  try { const f = $('Finalize Enriched Contact').first().json; if (f && f.contact) return f; } catch (e) {}
  return $('Load Draft Contact').first().json || {};
}
const ctx = draftCtx();
let sp = {};
try { sp = $input.first().json || {}; } catch (e) { sp = {}; }
const organic = Array.isArray(sp.organic) ? sp.organic : [];
const hook_sources = organic.slice(0, 6).map((r) => ({
  title: r.title || '', url: r.link || '', snippet: r.snippet || '',
})).filter((h) => h.title || h.snippet);

return [{ json: Object.assign({}, ctx, {
  candidate_role: ctx.role || ctx.candidate_role || '',
  contact_location: (ctx.contact || {}).location || null,
  hook_sources,
}) }];

// Build Enriched Contact — S8. Converge after the Apollo gate. Merges the Apollo
// match (work email + title) into the contact when Apollo ran; otherwise passes the
// free contact through unchanged. Carries hunter_enabled + has_email forward so the
// Hunter gate can decide cheaply. n8n throws on $('<unrun node>') — caught.
const ctx = $('Load Draft Contact').first().json || {};
const base = ctx.contact || {};

let cfg = {};
try { cfg = $('Load Enrich Config').first().json || {}; } catch (e) { cfg = {}; }

let person = null;
try {
  const a = $('Apollo Match').first().json || {};
  person = a.person || (Array.isArray(a.matches) && a.matches[0]) || (Array.isArray(a.people) && a.people[0]) || null;
} catch (e) { person = null; }

const email = (person && (person.email || person.work_email)) || base.email || null;
const title = (person && (person.title || person.headline)) || base.role || base.title || '';
const contact = Object.assign({}, base, {
  email: email || null,
  title: title,
  apollo_enriched: !!person,
});

return [{ json: Object.assign({}, ctx, {
  contact,
  has_email: !!email,
  hunter_enabled: cfg.hunter_enabled || 'false',
}) }];

// Finalize Enriched Contact — S8. Converge after the Hunter gate. Attaches the
// Hunter deliverability result (if Hunter ran) to the enriched contact, then hands
// the Load-Draft-Contact-shaped object (+ enrichment) to the hook lane. Graceful:
// if Hunter didn't run, email_verified stays null ("unverified"). $('<unrun>') caught.
const ctx = $('Build Enriched Contact').first().json || {};
const contact = ctx.contact || {};

let status = null, verified = null;
try {
  const h = $('Hunter Verify').first().json || {};
  status = h.status || h.result || (h.data && h.data.status) || null;
  if (status) verified = ['valid', 'deliverable', 'accept_all', 'webmail'].indexOf(String(status).toLowerCase()) !== -1;
} catch (e) { status = null; verified = null; }

const enrichedContact = Object.assign({}, contact, { email_status: status, email_verified: verified });

return [{ json: Object.assign({}, ctx, {
  contact: enrichedContact,
  email_verified: verified,
  enriched: !!(contact.apollo_enriched || status),
}) }];

// Format Costs — S9b. Turns the Load Costs rows (per-provider spend, last 30 days)
// into a Telegram message. Graceful when nothing is logged yet.
const chatId = $('Extract Input').first().json.chat_id;
const rows = $input.all().map((i) => i.json).filter((r) => r && r.provider);

if (!rows.length) {
  return [{ json: { chat_id: chatId, message: '💸 No tracked spend yet. Paid-provider usage (e.g. Apollo) is logged to tool_cost_log when those lanes run. LLM calls go through your OpenRouter account.' } }];
}

let total = 0, today = 0;
const lines = rows.map((r) => {
  const c = Number(r.cost || 0); total += c; today += Number(r.cost_today || 0);
  const u = Number(r.units || 0);
  return '• ' + r.provider + ': $' + c.toFixed(2) + ' — ' + r.calls + ' calls' + (u ? (', ' + u + ' units') : '');
});

const msg = '💸 *Spend — last 30 days*\n' + lines.join('\n')
  + '\n\n*Total:* $' + total.toFixed(2) + '   *Today:* $' + today.toFixed(2)
  + '\n\n_Tracked from tool_cost_log (paid providers). LLM calls are billed on your OpenRouter account._';

return [{ json: { chat_id: chatId, message: msg } }];

// Build Matcher Request — S13 + Phase 3. POST body for the matcher service:
// the full resume + the top-25 candidates (cache-first: source_priority -> rrf
// relevance -> tier -> recency) with FULL JD text, enrich=true. The matcher now
// reranks all 25, then validates the post-rerank top_n (true 2-pass), so input
// order only decides which 25 are sent, not what gets validated.
// Out: { resume_text, jobs, enrich, top_n }.
const bsi = $('Build Scorer Input').first().json || {};
const jobs = bsi.jobs || [];
const resume = bsi.master_resume_text || bsi.master_resume_summary || '';

// metadata for ordering/recency lives on the Aggregate Jobs records too
let metaById = {};
try {
  const agg = ($('Aggregate Jobs').first().json || {}).jobs || [];
  agg.forEach((j) => { if (j && j.job_id) metaById[j.job_id] = j; });
} catch (e) {}

const meta = (j) => metaById[j.job_id] || j;
const dateOf = (j) => { const m = meta(j); return new Date(m.posted_at || m.updated_at || j.updated_at || 0).getTime() || 0; };

const sorted = jobs.slice().sort((a, b) => {
  const ma = meta(a), mb = meta(b);
  const pa = ma.source_priority ?? a.source_priority ?? 1;
  const pb = mb.source_priority ?? b.source_priority ?? 1;
  if (pa !== pb) return pa - pb;                       // cache (0) before web (1)
  if (pa === 0) {
    const ra = ma.rrf_score || a.rrf_score || 0;
    const rb = mb.rrf_score || b.rrf_score || 0;
    if (rb !== ra) return rb - ra;                     // cache hybrid relevance
  }
  const t = (a.source_tier || 99) - (b.source_tier || 99);
  if (t !== 0) return t;
  return dateOf(b) - dateOf(a);
});

const top = sorted.slice(0, 25);
const payloadJobs = top.map((j) => ({
  id: j.job_id,
  title: [j.title, j.company].filter(Boolean).join(' at '),
  jd_text: j.jd_text || j.description_snippet || '',   // full cache JD when available
  url: j.url || '',
  source: j.ats_source || null,                        // Tier 2: real ATS provider for find-time liveness
  board: j.board || null,
  external_id: j.external_id || null,
  apply_url: j.apply_url || j.url || '',
}));

return [{ json: { resume_text: resume, jobs: payloadJobs, enrich: true, top_n: 15 } }];
